-- ============================================================
-- V70: Fresh GPU Component Catalog Seed
-- NVIDIA: GeForce GTX 10 / GTX 16 / RTX 20 / RTX 30 / RTX 40 / RTX 50 desktop
-- Intel: Arc A-Series / Arc B-Series desktop
-- AMD: Radeon RX 5000 / RX 6000 / RX 7000 / RX 9000 desktop
-- Laptop, mobile, workstation and AIB-only naming variants excluded.
-- Local reset friendly: existing GPU catalog rows are removed first.
-- ============================================================

DELETE FROM hardware_components
WHERE component_type = 'GPU';

INSERT INTO hardware_components (
    component_type,
    category,
    brand_id,
    series_name,
    model_name,
    normalized_name,
    vram_gb,
    extra_specs,
    verified,
    active
)
SELECT
    'GPU',
    'GRAPHICS_CARD',
    b.id,
    v.series_name,
    v.model_name,
    v.normalized_name,
    v.vram_gb,
    v.extra_specs,
    1,
    1
FROM (VALUES
('NVIDIA', 'NVIDIA GeForce GTX 10 Series', 'GeForce GTX 1050 2GB', 'geforce gtx 1050 2gb', 2, 'Desktop; NVIDIA GeForce GTX 10 Series; Pascal'),
